import re,os,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def regions(g, bg=8):
    # maximal 0-blocks: rows/cols where zeros appear; find connected 0-rectangles via bounding boxes of 0-cells clusters
    h,w=len(g),len(g[0])
    seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==0 and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    r,c=stack.pop(); cells.append((r,c))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<h and 0<=nc<w and g[nr][nc]==0 and not seen[nr][nc]:
                            seen[nr][nc]=True; stack.append((nr,nc))
                rs=[r for r,_ in cells]; cs=[c for _,c in cells]
                out.append((min(rs),min(cs),max(rs),max(cs)))
    return out

def transform(g, bg=8):
    g=[row[:] for row in g]
    for r0,c0,r1,c1 in regions(g,bg):
        rh,cw=r1-r0+1,c1-c0+1
        # bbox of nonzero cells inside region
        nz=[(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1) if g[r][c]!=0]
        pr0=min(r for r,_ in nz); pr1=max(r for r,_ in nz)
        pc0=min(c for _,c in nz); pc1=max(c for _,c in nz)
        pat=[row[pc0:pc1+1] for row in g[pr0:pr1+1]]
        ph,pw=len(pat),len(pat[0])
        orr,occ=pr0-r0,pc0-c0
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                g[r][c]=pat[(r-r0-orr)%ph][(c-c0-occ)%pw]
    return g

d=G['Demo pair 1 input']; o=G['Demo pair 1 output']
print(transform(d)==o)
t=transform(G['Test input'])
for row in t: print(' '.join(map(str,row)))

